SELECT min(order_purchase_timestamp), max(order_purchase_timestamp)
FROM orders
WHERE order_purchase_timestamp >= '2017-11-01' AND order_purchase_timestamp < '2017-12-01';

SELECT MIN(order_purchase_timestamp), MAX(order_purchase_timestamp) 
FROM orders 
WHERE order_status = 'canceled' AND EXTRACT(YEAR FROM order_purchase_timestamp) = 2017;

SELECT min(order_purchase_timestamp), max(order_purchase_timestamp)
FROM orders
WHERE EXTRACT(YEAR FROM order_purchase_timestamp) = 2018;

select c.customer_state, sum(oi.price) gmv, sum(oi.price) filter (where o.order_status not in ('canceled','unavailable')) gmv_ex
from orders o join order_items oi using(order_id) join customers c using(customer_id)
where year(o.order_purchase_timestamp)=2018 group by 1 order by 2 desc limit 6

select coalesce(t.product_category_name_english,p.product_category_name,'unknown') c, sum(oi.price) gmv, sum(case when o.order_status not in ('canceled','unavailable') then oi.price end) gmv_ex
from order_items oi join orders o using(order_id) left join products p using(product_id) left join product_category_name_translation t using(product_category_name)
where year(o.order_purchase_timestamp)=2017 group by 1 order by 2 desc limit 7

SELECT product_category_name, product_category_name_english 
FROM product_category_name_translation 
WHERE product_category_name IN ('cama_mesa_banho', 'relogios_presentes', 'beleza_saude', 'esporte_lazer', 'informatica_acessorios');

SELECT MIN(order_purchase_timestamp), MAX(order_purchase_timestamp) 
FROM orders 
WHERE EXTRACT(YEAR FROM order_purchase_timestamp) = 2018;

WITH v AS (
  SELECT c.customer_unique_id, o.order_purchase_timestamp
  FROM orders o JOIN customers c ON o.customer_id = c.customer_id
  WHERE o.order_status NOT IN ('canceled','unavailable')
),
f AS (
  SELECT customer_unique_id, MIN(order_purchase_timestamp) AS first_order FROM v GROUP BY 1
)
SELECT COUNT(*) AS new_customers_2018 FROM f WHERE first_order >= '2018-01-01' AND first_order < '2019-01-01';

SELECT 
    2997.0 / 96096.0 AS fraction,
    (2997.0 / 96096.0) * 100 AS percentage;

select count(*) d, sum(case when cast(o.order_delivered_customer_date as date) > cast(o.order_estimated_delivery_date as date) then 1 else 0 end) late
from orders o join customers c using(customer_id)
where c.customer_state='AL' and o.order_status='delivered' and o.order_delivered_customer_date is not null
